import Foundation

enum Endpoints {
    static let baseURL = URL(string: "https://api.example.com/v2")!

    static func orders(for customerID: String) -> URL {
        baseURL.appendingPathComponent("customers")
            .appendingPathComponent(customerID)
            .appendingPathComponent("orders")
    }

    static func orderDetail(orderID: String) -> URL {
        baseURL.appendingPathComponent("orders").appendingPathComponent(orderID)
    }
}

import Foundation

struct SearchRequestBuilder {
    let baseURL: URL

    func makeRequest(query: String, page: Int) -> URLRequest {
        var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false)
        components?.path = "/search"
        components?.queryItems = [
            URLQueryItem(name: "q", value: query),
            URLQueryItem(name: "page", value: String(page)),
        ]
        var request = URLRequest(url: components!.url!)
        request.httpMethod = "GET"
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        return request
    }
}

