import Foundation

final class OrderSyncObserver {
    private var observerToken: NSObjectProtocol?
    private let onOrderUpdated: (Order) -> Void

    init(center: NotificationCenter = .default, onOrderUpdated: @escaping (Order) -> Void) {
        self.onOrderUpdated = onOrderUpdated
        observerToken = center.addObserver(forName: .orderDidSync, object: nil, queue: .main) { [weak self] notification in
            guard let self, let userInfo = notification.userInfo else { return }
            let order = userInfo["order"] as! Order
            self.onOrderUpdated(order)
        }
    }

    deinit {
        if let observerToken {
            NotificationCenter.default.removeObserver(observerToken)
        }
    }
}

