import ArgumentParser
import Foundation

@main
struct RenameAssets: ParsableCommand {
    static let configuration = CommandConfiguration(
        abstract: "Renames image assets to kebab-case."
    )

    @Argument(help: "Directory containing the assets.")
    var directory: String

    @Flag(help: "Show what would change without renaming anything.")
    var dryRun = false

    func run() throws {
        let fileManager = FileManager.default
        let directoryURL = URL(fileURLWithPath: directory)
        let fileNames = try fileManager.contentsOfDirectory(atPath: directory)
        var renamedCount = 0

        for fileName in fileNames {
            let kebabName = fileName.kebabCased()
            guard kebabName != fileName else { continue }
            print("\(fileName) -> \(kebabName)")
            if !dryRun {
                try fileManager.moveItem(
                    at: directoryURL.appendingPathComponent(fileName),
                    to: directoryURL.appendingPathComponent(kebabName)
                )
            }
            renamedCount += 1
        }

        print(dryRun ? "Would rename \(renamedCount) files." : "Renamed \(renamedCount) files.")
    }
}

