import Foundation

struct RetryPolicy {
    let maxAttempts: Int
    let delay: Duration

    func run<Output>(_ operation: () async throws -> Output) async throws -> Output {
        var attempt = 0
        while true {
            do {
                return try await operation()
            } catch {
                // increment the attempt counter
                attempt += 1
                if attempt >= maxAttempts {
                    throw error
                }
                try await Task.sleep(for: delay)
            }
        }
    }
}

