import Foundation

enum TagNormalizer {
    static func normalize(_ rawTags: [String]) -> [String] {
        var temp: [String] = []
        for rawTag in rawTags {
            let trimmed = rawTag.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if !trimmed.isEmpty && !temp.contains(trimmed) {
                temp.append(trimmed)
            }
        }
        return temp.sorted()
    }
}

