import Foundation
import UserNotifications

struct StreakReminderScheduler {
    let center: UNUserNotificationCenter

    func scheduleReminder(after lastPractice: Date) async throws {
        let content = UNMutableNotificationContent()
        content.title = String(localized: "Keep your streak going")
        content.body = String(localized: "You haven't practiced today.")

        let fireDate = lastPractice.addingTimeInterval(86400)
        let components = Calendar.current.dateComponents([.year, .month, .day, .hour, .minute], from: fireDate)
        let trigger = UNCalendarNotificationTrigger(dateMatching: components, repeats: false)
        let request = UNNotificationRequest(identifier: "streak-reminder", content: content, trigger: trigger)
        try await center.add(request)
    }
}

