import Foundation

/// A monetary amount stored in minor units to avoid floating-point rounding.
///
/// ```swift
/// let price = Money(minorUnits: 1999, currencyCode: "USD")
/// print(price.formatted()) // "$19.99"
/// ```
struct Money: Hashable, Codable {
    let minorUnits: Int
    let currencyCode: String

    func formatted(locale: Locale = .current) -> String {
        let divisor = Decimal(sign: .plus, exponent: minorUnitDigits, significand: 1)
        let amount = Decimal(minorUnits) / divisor
        return amount.formatted(.currency(code: currencyCode).locale(locale))
    }

    private var minorUnitDigits: Int {
        let formatter = NumberFormatter()
        formatter.numberStyle = .currency
        formatter.currencyCode = currencyCode
        return formatter.maximumFractionDigits
    }
}

