enum APIError: Error, Equatable {
    case invalidResponse
    case unexpectedStatus(Int)
}

enum HTTPStatus {
    static let success = 200..<300
}

struct GitHubClient: Sendable {
    private let session: URLSession
    private let baseURL: URL
    private let tokenProvider: @Sendable () async throws -> String
    private let logger = Logger(subsystem: "com.example.repobrowser", category: "GitHubClient")

    init(
        session: URLSession = .shared,
        baseURL: URL,
        tokenProvider: @escaping @Sendable () async throws -> String
    ) {
        self.session = session
        self.baseURL = baseURL
        self.tokenProvider = tokenProvider
    }

    func repositories(forUser username: String) async throws -> [Repository] {
        let endpoint = baseURL
            .appendingPathComponent("users")
            .appendingPathComponent(username)
            .appendingPathComponent("repos")
        return try await fetchJSON(from: endpoint)
    }

    func repository(owner: String, name: String) async throws -> Repository {
        let endpoint = baseURL
            .appendingPathComponent("repos")
            .appendingPathComponent(owner)
            .appendingPathComponent(name)
        return try await fetchJSON(from: endpoint)
    }

    private func fetchJSON<Response: Decodable>(from endpoint: URL) async throws -> Response {
        let accessToken = try await tokenProvider()
        var request = URLRequest(url: endpoint)
        request.setValue("application/vnd.github+json", forHTTPHeaderField: "Accept")
        request.setValue("Bearer \(accessToken)", forHTTPHeaderField: "Authorization")

        let (responseBody, response) = try await session.data(for: request)
        guard let httpResponse = response as? HTTPURLResponse else {
            throw APIError.invalidResponse
        }
        guard HTTPStatus.success.contains(httpResponse.statusCode) else {
            logger.error("GET \(endpoint.path, privacy: .public) failed with status \(httpResponse.statusCode)")
            throw APIError.unexpectedStatus(httpResponse.statusCode)
        }
        return try JSONDecoder.github.decode(Response.self, from: responseBody)
    }
}

