+import Foundation
+
+/// Delays an action until calls stop arriving for `interval`, so typing in a
+/// search field triggers one request instead of one per keystroke.
+actor Debouncer {
+    private let interval: Duration
+    private var pendingTask: Task<Void, Never>?
+
+    init(interval: Duration) {
+        self.interval = interval
+    }
+
+    func submit(_ action: @escaping @Sendable () async -> Void) {
+        pendingTask?.cancel()
+        pendingTask = Task { [interval] in
+            do {
+                try await Task.sleep(for: interval)
+            } catch {
+                return
+            }
+            await action()
+        }
+    }
+}
