import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var targetPerWeek: Int
    @Relationship(deleteRule: .cascade, inverse: \CheckIn.habit)
    var checkIns: [CheckIn] = []

    init(name: String, targetPerWeek: Int, createdAt: Date = .now) {
        self.name = name
        self.targetPerWeek = targetPerWeek
        self.createdAt = createdAt
    }

    func checkIns(inWeekOf referenceDate: Date, calendar: Calendar = .current) -> [CheckIn] {
        guard let weekInterval = calendar.dateInterval(of: .weekOfYear, for: referenceDate) else {
            return []
        }
        return checkIns.filter { weekInterval.contains($0.completedAt) }
    }

    func isOnTrack(inWeekOf referenceDate: Date) -> Bool {
        checkIns(inWeekOf: referenceDate).count >= targetPerWeek
    }
}

@Model
final class CheckIn {
    var completedAt: Date
    var habit: Habit?

    init(completedAt: Date = .now, habit: Habit? = nil) {
        self.completedAt = completedAt
        self.habit = habit
    }
}

