@MainActor
@Observable
final class ContactListModel {
    private(set) var contacts: [Contact] = []
    private(set) var isLoading = false
    private(set) var loadError: String?
    var searchText = ""

    private let directory: ContactDirectory

    init(directory: ContactDirectory) {
        self.directory = directory
    }

    var filteredContacts: [Contact] {
        let query = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !query.isEmpty else { return contacts }
        return contacts.filter { contact in
            contact.displayName.localizedCaseInsensitiveContains(query)
                || (contact.email?.localizedCaseInsensitiveContains(query) ?? false)
        }
    }

    var sections: [ContactSection] {
        let contactsByInitial = Dictionary(grouping: filteredContacts) { contact in
            contact.displayName.first.map { String($0).uppercased() } ?? "#"
        }
        return contactsByInitial
            .map { ContactSection(initial: $0.key, contacts: $0.value.sorted { $0.displayName < $1.displayName }) }
            .sorted { $0.initial < $1.initial }
    }

    func load() async {
        isLoading = true
        defer { isLoading = false }
        do {
            contacts = try await directory.allContacts()
            loadError = nil
        } catch {
            loadError = error.localizedDescription
        }
    }

    func delete(_ contact: Contact) async {
        do {
            try await directory.delete(contactID: contact.id)
            contacts.removeAll { $0.id == contact.id }
        } catch {
            loadError = error.localizedDescription
        }
    }
}

struct ContactSection: Identifiable {
    let initial: String
    let contacts: [Contact]

    var id: String { initial }
}

struct ContactListView: View {
    @State private var model: ContactListModel

    init(directory: ContactDirectory) {
        _model = State(initialValue: ContactListModel(directory: directory))
    }

    var body: some View {
        NavigationStack {
            Group {
                if model.isLoading && model.contacts.isEmpty {
                    ProgressView("Loading contacts")
                } else if let loadError = model.loadError, model.contacts.isEmpty {
                    ContentUnavailableView {
                        Label("Couldn't load contacts", systemImage: "person.crop.circle.badge.exclamationmark")
                    } description: {
                        Text(loadError)
                    } actions: {
                        Button("Try Again") {
                            Task { await model.load() }
                        }
                    }
                } else {
                    contactList
                }
            }
            .navigationTitle("Contacts")
            .searchable(text: $model.searchText)
            .task { await model.load() }
            .refreshable { await model.load() }
        }
    }

    private var contactList: some View {
        List {
            ForEach(model.sections) { section in
                Section(section.initial) {
                    ForEach(section.contacts) { contact in
                        NavigationLink(value: contact) {
                            ContactRow(contact: contact)
                        }
                        .swipeActions {
                            Button("Delete", role: .destructive) {
                                Task { await model.delete(contact) }
                            }
                        }
                    }
                }
            }
        }
        .navigationDestination(for: Contact.self) { contact in
            ContactDetailView(contact: contact)
        }
    }
}

