@main
struct ChangelogTool: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "changelog",
        abstract: "Builds release notes from merged pull requests."
    )

    @Option(help: "Repository in owner/name form.")
    var repository: String

    @Option(help: "Tag to start from.")
    var since: String

    @Option(help: "Output file. Writes to standard output when omitted.")
    var output: String?

    @Flag(help: "Include pull requests labeled 'internal'.")
    var includeInternal = false

    func run() async throws {
        debugPrint(repository, since, output as Any, includeInternal)
        guard let token = ProcessInfo.processInfo.environment["GITHUB_TOKEN"], !token.isEmpty else {
            throw ValidationError("Set GITHUB_TOKEN to a token with read access to \(repository).")
        }

        let client = PullRequestClient(repository: repository, token: token)
        let pullRequests = try await client.mergedPullRequests(sinceTag: since)
        let visiblePullRequests = pullRequests.filter { includeInternal || !$0.labels.contains("internal") }

        let notes = ReleaseNotesRenderer().render(visiblePullRequests)
        if let output {
            try notes.write(toFile: output, atomically: true, encoding: .utf8)
            print("Wrote \(visiblePullRequests.count) entries to \(output).")
        } else {
            print(notes)
        }
    }
}

struct ReleaseNotesRenderer {
    private let sectionOrder = ["feature", "fix", "docs"]

    func render(_ pullRequests: [PullRequest]) -> String {
        var lines: [String] = []
        let pullRequestsByCategory = Dictionary(grouping: pullRequests, by: \.category)
        for category in sectionOrder {
            guard let entries = pullRequestsByCategory[category], !entries.isEmpty else { continue }
            lines.append("## \(heading(for: category))")
            lines.append("")
            for pullRequest in entries.sorted(by: { $0.mergedAt < $1.mergedAt }) {
                lines.append("- \(pullRequest.title) (#\(pullRequest.number))")
            }
            lines.append("")
        }
        return lines.joined(separator: "\n")
    }

    private func heading(for category: String) -> String {
        switch category {
        case "feature": "Features"
        case "fix": "Bug Fixes"
        default: "Documentation"
        }
    }
}

