final class StoreLocatorViewController: UIViewController {
    private enum Search {
        static let radius: CLLocationDistance = 25_000
    }

    private let mapView = MKMapView()
    private let locationManager = CLLocationManager()
    private let storeDirectory: StoreDirectory
    private let logger = Logger(subsystem: "com.example.shop", category: "StoreLocator")
    private var stores: [Store] = []

    init(storeDirectory: StoreDirectory) {
        self.storeDirectory = storeDirectory
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) is not supported")
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        title = String(localized: "Find a Store")
        mapView.delegate = self
        mapView.showsUserLocation = true
        mapView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(mapView)
        NSLayoutConstraint.activate([
            mapView.topAnchor.constraint(equalTo: view.topAnchor),
            mapView.bottomAnchor.constraint(equalTo: view.bottomAnchor),
            mapView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            mapView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
        ])
        locationManager.delegate = self
        locationManager.requestWhenInUseAuthorization()
    }

    private func showStores(near coordinate: CLLocationCoordinate2D) {
        Task {
            do {
                stores = try await storeDirectory.stores(near: coordinate, radius: Search.radius)
                mapView.removeAnnotations(mapView.annotations)
                mapView.addAnnotations(stores.map(StoreAnnotation.init))
                let region = MKCoordinateRegion(
                    center: coordinate,
                    latitudinalMeters: Search.radius,
                    longitudinalMeters: Search.radius
                )
                mapView.setRegion(region, animated: true)
            } catch {
                logger.error("Store lookup failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }
}

extension StoreLocatorViewController: CLLocationManagerDelegate {
    func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        if manager.authorizationStatus == .authorizedWhenInUse {
            manager.requestLocation()
        }
    }

    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard let latestLocation = locations.last else { return }
        showStores(near: latestLocation.coordinate)
    }

    func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        logger.error("Location update failed: \(error.localizedDescription, privacy: .public)")
    }
}

extension StoreLocatorViewController: MKMapViewDelegate {
    func mapView(_ mapView: MKMapView, didSelect annotation: MKAnnotation) {
        if let storeAnnotation = annotation as? StoreAnnotation {
            if let store = stores.first(where: { $0.id == storeAnnotation.storeID }) {
                if store.isOpen(at: .now) {
                    let detailController = StoreDetailViewController(store: store)
                    navigationController?.pushViewController(detailController, animated: true)
                }
            }
        }
    }
}

