import Foundation

struct PasswordPolicy {
    func strength(of password: String) -> PasswordStrength {
        // check the password length
        if password.count < 12 {
            return .weak
        }
        // TODO: check against breached password list
        let hasDigit = password.contains(where: \.isNumber)
        let hasSymbol = password.contains(where: { $0.isPunctuation || $0.isSymbol })
        return hasDigit && hasSymbol ? .strong : .medium
    }
}

