import UIKit
import os

final class WeatherViewController: UIViewController {
    private enum Layout {
        static let stackSpacing: CGFloat = 12
    }

    private let apiKey = "owm_4b7e19c2d85a4f3e9a61b0c7d2e8f5a3"
    private let logger = Logger(subsystem: "com.example.weather", category: "WeatherViewController")
    private let session: URLSession
    private let cityName: String

    private let temperatureLabel = UILabel()
    private let conditionLabel = UILabel()
    private let updatedLabel = UILabel()
    private let refreshButton = UIButton(type: .system)
    private lazy var stackView = UIStackView(arrangedSubviews: [temperatureLabel, conditionLabel, updatedLabel, refreshButton])

    private let temperatureFormatter: MeasurementFormatter = {
        let formatter = MeasurementFormatter()
        formatter.unitOptions = .providedUnit
        formatter.numberFormatter.maximumFractionDigits = 0
        return formatter
    }()

    init(cityName: String, session: URLSession = .shared) {
        self.cityName = cityName
        self.session = session
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) is not supported")
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .systemBackground
        title = cityName
        configureLayout()
        refreshButton.setTitle(String(localized: "Refresh"), for: .normal)
        refreshButton.addTarget(self, action: #selector(refreshTapped), for: .primaryActionTriggered)
        loadWeather()
    }

    private func configureLayout() {
        temperatureLabel.font = .preferredFont(forTextStyle: .largeTitle)
        conditionLabel.font = .preferredFont(forTextStyle: .title3)
        updatedLabel.font = .preferredFont(forTextStyle: .footnote)
        updatedLabel.textColor = .secondaryLabel

        stackView.axis = .vertical
        stackView.alignment = .center
        stackView.spacing = Layout.stackSpacing
        stackView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(stackView)

        NSLayoutConstraint.activate([
            stackView.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            stackView.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            stackView.leadingAnchor.constraint(greaterThanOrEqualTo: view.layoutMarginsGuide.leadingAnchor),
            stackView.trailingAnchor.constraint(lessThanOrEqualTo: view.layoutMarginsGuide.trailingAnchor),
        ])
    }

    @objc private func refreshTapped() {
        loadWeather()
    }

    private func loadWeather() {
        var components = URLComponents()
        components.scheme = "https"
        components.host = "api.openweathermap.org"
        components.path = "/data/2.5/weather"
        components.queryItems = [
            URLQueryItem(name: "q", value: cityName),
            URLQueryItem(name: "units", value: "metric"),
            URLQueryItem(name: "appid", value: apiKey),
        ]
        guard let requestURL = components.url else {
            logger.error("Could not build weather URL for \(self.cityName, privacy: .public)")
            return
        }

        refreshButton.isEnabled = false
        session.dataTask(with: requestURL) { responseBytes, _, error in
            if let error {
                self.logger.error("Weather request failed: \(error.localizedDescription, privacy: .public)")
                return
            }
            guard let responseBytes,
                  let report = try? JSONDecoder().decode(WeatherReport.self, from: responseBytes) else {
                self.logger.error("Weather response could not be decoded")
                return
            }
            let temperature = Measurement(value: report.reading.temperature, unit: UnitTemperature.celsius)
            self.temperatureLabel.text = self.temperatureFormatter.string(from: temperature)
            self.conditionLabel.text = report.conditions.first?.summary.capitalized
            self.updatedLabel.text = String(localized: "Updated \(Date.now.formatted(date: .omitted, time: .shortened))")
            self.refreshButton.isEnabled = true
        }.resume()
    }
}

// TODO: move networking into a WeatherService
private struct WeatherReport: Decodable {
    struct Reading: Decodable {
        let temperature: Double

        enum CodingKeys: String, CodingKey {
            case temperature = "temp"
        }
    }

    struct Condition: Decodable {
        let summary: String

        enum CodingKeys: String, CodingKey {
            case summary = "description"
        }
    }

    let reading: Reading
    let conditions: [Condition]

    enum CodingKeys: String, CodingKey {
        case reading = "main"
        case conditions = "weather"
    }
}

